const raw = $input.item.json.output;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    sender: "unknown",
    topic: null,
    proposed_time: null,
    urgency: "medium",
    decision: "need_more_info",
    missing_info: ["Could not parse AI response: " + e.message],
    draft_response: null,
    event_start: null,
    event_end: null
  };
}

return { json: parsed };

